/* Local ingredient intentions, shared by the atlas and the two drawing pages. */
(function(root){
 'use strict';
 const KEY='fengwu.food-records.v1',I=root.IngredientIdentity,foods=I?I.catalog(root.FOODS||[]):root.FOODS||[],byId=Object.fromEntries(foods.map(f=>[f.id,f])),canonical=id=>I?I.key(id):id;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const visible=id=>!root.ReaderAccess||root.ReaderAccess.visible(byId[id]);
 let items={},durable=true,filter='want',dialog;
 function load(){try{const raw=localStorage.getItem(KEY);if(!raw){items={};return;}if(raw.length>50000)throw Error();const data=JSON.parse(raw);if(data.version!==1)throw Error();const valid=Object.fromEntries(Object.entries(data.items||{}).filter(([id,v])=>Object.hasOwn(byId,canonical(id))&&['want','tried'].includes(v?.state)&&Number.isFinite(v.updatedAt)));items=I?I.migrate(valid):valid;}catch{durable=false;}}
 function render(food){if(root.ReaderAccess&&!root.ReaderAccess.visible(food))return '';const f=I?I.present(food):food;return `<div class="food-record-controls" data-record-food="${esc(f.id)}" role="group" aria-label="记录${esc(f.name)}"><button type="button" data-record-state="want" aria-pressed="false"><span aria-hidden="true">♡</span> 我想试</button><button type="button" data-record-state="tried" aria-pressed="false"><span aria-hidden="true">✓</span> 我吃过</button><small class="record-feedback" role="status"></small></div>`;}
 function sync(){document.querySelectorAll('[data-record-food]').forEach(el=>{const state=items[canonical(el.dataset.recordFood)]?.state;el.querySelectorAll('[data-record-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.recordState===state)));});document.querySelectorAll('[data-record-count]').forEach(el=>el.textContent=Object.keys(items).filter(visible).length||'');}
 function list(){if(!dialog)return;const ids=Object.keys(items).filter(id=>visible(id)&&items[id].state===filter).sort((a,b)=>items[b].updatedAt-items[a].updatedAt);dialog.querySelectorAll('[data-record-filter]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.recordFilter===filter));b.querySelector('small').textContent=Object.entries(items).filter(([id,v])=>visible(id)&&v.state===b.dataset.recordFilter).length;});dialog.querySelector('.records-list').innerHTML=ids.length?ids.map(id=>{const f=byId[id],photo=root.FoodMedia?.ingredient(f)||f.identityPhoto;return `<article class="record-entry"><a href="index.html?food=${encodeURIComponent(id)}"><span class="record-photo">${photo?.src||f.cardImage||f.image?`<img src="${esc(photo?.src||f.cardImage||f.image)}" alt="${esc(photo?.alt||f.cardImageAlt||f.imageAlt||f.name)}" loading="lazy" decoding="async"><small class="record-photo-note">${esc(photo?.note||f.cardNote||f.imageCaption||'形态参考 · 非产地鉴别')}</small>`:'<span class="record-photo-empty">图片待补</span>'}</span><span><small>${esc(f.region)}</small><strong>${esc(f.name)}</strong><em>再读这一味 ↗</em></span></a>${render(f)}</article>`;}).join(''):`<div class="records-empty"><span aria-hidden="true">${filter==='want'?'♡':'✓'}</span><h3>${filter==='want'?'把下一次好奇，留在这里。':'尝过的一口，值得记住。'}</h3><p>${filter==='want'?'读到心动的一味，点一下「我想试」。':'尝鲜之后，点一下「我吃过」。'}</p><a href="index.html">沿节气，再去逛逛 ↗</a></div>`;sync();}
 function open(){if(!dialog){dialog=document.createElement('dialog');dialog.className='records-dialog social-dialog';dialog.setAttribute('aria-labelledby','records-title');dialog.innerHTML=`<header class="social-dialog-head"><p>时令风物 · 我的尝鲜</p><button type="button" data-close-records aria-label="关闭我的尝鲜">关闭 ×</button></header><div class="social-dialog-body"><h2 id="records-title">把心动，留到下一餐。</h2><p class="social-fine records-privacy">${durable?'仅保存在当前浏览器；换设备或清除浏览数据后不会保留。':'浏览器未允许保存；本次记录仅在当前页面停留期间可用。'}</p><div class="record-filters" role="group" aria-label="按尝鲜记录筛选"><button type="button" data-record-filter="want" aria-pressed="true">我想试 <small>0</small></button><button type="button" data-record-filter="tried" aria-pressed="false">我吃过 <small>0</small></button></div><div class="records-list"></div><p class="social-fine" role="status" id="records-status"></p></div>`;document.body.append(dialog);}list();dialog.showModal();}
 load();
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-open-records'))return open();if(b.hasAttribute('data-close-records'))return dialog.close();if(b.dataset.recordFilter){filter=b.dataset.recordFilter;return list();}const el=b.closest('[data-record-food]');if(!el||!b.dataset.recordState)return;const id=canonical(el.dataset.recordFood),state=b.dataset.recordState;if(!byId[id])return;const removed=items[id]?.state===state;if(removed)delete items[id];else items[id]={state,updatedAt:Date.now()};try{localStorage.setItem(KEY,JSON.stringify({version:1,items}));durable=true;}catch{durable=false;}sync();const message=(removed?'已取消':state==='want'?'已记下，留待尝鲜':'记下这一口')+(durable?'':' · 未能保存到浏览器，仅本页有效');el.querySelector('.record-feedback').textContent=message;if(dialog?.open){list();dialog.querySelector('#records-status').textContent=message;dialog.querySelector('.records-privacy').textContent=durable?'仅保存在当前浏览器；换设备或清除浏览数据后不会保留。':'浏览器未允许保存；本次记录仅在当前页面停留期间可用。';(dialog.querySelector(`[data-record-food="${id}"] [data-record-state="${state}"]`)||dialog.querySelector('[data-record-filter][aria-pressed=true]')).focus({preventScroll:true});}});
 root.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){load();sync();if(dialog?.open)list();}});
 root.FoodRecords={render,bind:sync,open};sync();
})(window);
